What is printed?
```
FILE *fp = fopen("n.txt", "w");
int x, s = 0;
fprintf(fp, "4 7 ");
fclose(fp);
fp = fopen("n.txt", "a");
fprintf(fp, "10");
fclose(fp);
fp = fopen("n.txt", "r");
while (fscanf(fp, "%d", &x) == 1)
    s += x;
fclose(fp);
printf("%d", s);
